/**
 * Masked password dialog for sap-profile-cli.
 *
 * Opens a native window outside the Claude Code chat so the password is
 * typed there and never enters the conversation transcript:
 *   - Windows: PowerShell + WinForms dialog (masked text box, topmost)
 *   - macOS:   osascript `display dialog ... with hidden answer`
 *   - Linux:   zenity --password, then kdialog --password
 *
 * The secret comes back over the child's stdout pipe only. Title / message are
 * passed through environment variables, never spliced into script text.
 *
 * promptPassword() resolves to the password string, or null when the user
 * cancels. It throws PasswordPromptUnavailableError when no dialog can open
 * (headless session, no GUI tool installed).
 */

import { spawnSync } from 'node:child_process';

const TIMEOUT_MS = 5 * 60 * 1000;

export class PasswordPromptUnavailableError extends Error {
  constructor(detail) {
    super(`password dialog unavailable: ${detail}`);
    this.code = 'ERR_PASSWORD_PROMPT_UNAVAILABLE';
  }
}

// Output protocol: "OK:<base64 of UTF-8 bytes>" or "CANCEL". Base64 keeps
// non-ASCII passwords intact regardless of the console code page.
